package com.jayptucker.heroesevolved.endgame;

import com.google.gson.JsonParser;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;

/** Stamina and channel times are generated by tools/balance.py, like the stronghold ritual. */
public final class EndTuning {
    public static final int CHANNEL_TICKS;
    public static final double CHANNEL_DRAIN;
    static {
        try(var stream=EndTuning.class.getResourceAsStream("/data/heroesevolved/end_battle_ritual.json")){
            if(stream==null)throw new IllegalStateException("Missing generated End battle tuning");
            var json=JsonParser.parseReader(new InputStreamReader(stream,StandardCharsets.UTF_8)).getAsJsonObject();
            CHANNEL_TICKS=json.get("channel_ticks").getAsInt();CHANNEL_DRAIN=json.get("drain_per_second").getAsDouble();
        }catch(Exception e){throw new ExceptionInInitializerError(e);}
    }
    private EndTuning(){}
}
